class Solution {
public:
    int peopleAwareOfSecret(int n, int delay, int forget) {
        const int MOD = 1e9 + 7;
        vector<long long> dp(n + 1, 0);
        dp[1] = 1;
        long long shareSum = 0;
        for (int j = 2; j <= n; j++) {
            if (j - delay >= 1)
                shareSum = (shareSum + dp[j - delay]) % MOD;
            if (j - forget >= 1)
                shareSum = (shareSum - dp[j - forget] + MOD) % MOD;
            dp[j] = shareSum;
        }
        long long ans = 0;
        for (int i = n - forget + 1; i <= n; i++)
            if (i >= 1) ans = (ans + dp[i]) % MOD;
        return (int)ans;
    }
};
